def double(value):
    if type(value) is not int:
        raise ValueError("Expected integer")
    return value * 2

source.target/check_contract.py:
from arithmetic import double
for value, expected in [(0,0),(-7,-14),(13,26),(10**30,2*10**30)]:
    assert double(value) == expected
for value in [True,False,"7",None,1.5]:
    try: double(value)
    except ValueError: pass
    else: raise AssertionError("Non-integer was accepted")
print("contract checks passed")

